style.css:
@-moz-document domain("roblox.com") {
/* Set background to a vintage Roblox theme */
    body {
        background-color: #e5e5e5 !important;
        color: #333 !important;
        font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif !important;
    }

    /* Roblox logo */
    #roblox-logo {
        width: 240px !important;
        height: 50px !important;
        background: url('https://www.roblox.com/asset/?id=458829073') no-repeat center center !important;
        background-size: contain !important;
    }

    /* Navbar background and text */
    .navbar {
        background-color: #313131 !important;
        color: #fff !important;
    }

    .navbar a {
        color: #fff !important;
        text-decoration: none !important;
        font-weight: bold !important;
    }

    /* Links and buttons */
    a {
        color: #0074cc !important;
    }

    a:hover {
        color: #ff5500 !important;
        text-decoration: underline !important;
    }

    /* Header styles */
    .header-container {
        background-color: #1e1e1e !important;
        padding: 10px !important;
    }

    .header-container h1 {
        color: #fff !important;
    }

    /* Buttons */
    button, .btn {
        background-color: #0074cc !important;
        border: 1px solid #0061a8 !important;
        color: #fff !important;
        padding: 5px 15px !important;
        font-size: 14px !important;
        font-weight: bold !important;
    }

    button:hover, .btn:hover {
        background-color: #0061a8 !important;
    }

    /* Style for the user profile area */
    .user-profile {
        background-color: #2f2f2f !important;
        color: #fff !important;
        padding: 10px !important;
        border-radius: 5px !important;
    }

    /* Sidebar */
    .sidebar {
        background-color: #333 !important;
        padding: 20px !important;
        border-radius: 5px !important;
    }

    .sidebar .title {
        font-size: 18px !important;
        font-weight: bold !important;
        color: #fff !important;
    }

    /* Classic navigation */
    .nav-list {
        background-color: #2f2f2f !important;
        border-radius: 5px !important;
        padding: 10px !important;
    }

    .nav-list a {
        color: #fff !important;
        font-weight: bold !important;
    }

    /* Banner area */
    .banner {
        background-color: #ff5500 !important;
        color: #fff !important;
        padding: 15px !important;
        font-size: 20px !important;
    }

    /* Footer */
    .footer {
        background-color: #1e1e1e !important;
        color: #fff !important;
        padding: 15px !important;
        font-size: 12px !important;
        text-align: center !important;
    }

    /* Content background */
    .content-area {
        background-color: #fff !important;
        border: 1px solid #ccc !important;
        padding: 20px !important;
        margin: 20px 0 !important;
        border-radius: 5px !important;
    }
}
